Task<int> Step(int i) => Task.FromResult(i);

// explicit continuation = a delegate receiving the result
Task.WhenAll(ids.Select(Step))
    .ContinueWith(t => Console.WriteLine(t.Result.Count))
    .ContinueWith(t => Console.Error.WriteLine(t.Exception), TaskContinuationOptions.OnlyOnFaulted);

async Task<int> TotalAsync(IEnumerable<int> ids) {
    var n = 0;
    foreach (var id in ids) n += await Step(id);   // CPS under the sugar
    return n;
}
